import React, { Component } from 'react'
import { connect } from 'react-redux'
import DocumentsGroupStyle from './index.style'
import {
  Row,
  Col,
  Icon,
  Upload,
  message
} from 'antd'
import { injectIntl } from 'react-intl'
import PropTypes from 'prop-types'
import userActions from '../../../../redux/user/actions'
import IntlMessages from '../../../../components/utility/intlMessages'
import DocumentItem from '../DocumentsItem'

const {
  uploadUserFile,
  postUserDocuments
} = userActions

class DocumentsGroup extends Component {
  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  customRequest = ({ file }) => {
    /*
      custom request to upload file
    */
    const { type: fileType } = file
    const { type: documentType } = this.props
    const validImageTypes = ['image/gif', 'image/jpeg', 'image/png', 'application/pdf', 'application/msword']
    if (validImageTypes.includes(fileType)) {
      const formData = new FormData()
      formData.append('file', file)
      this.props.uploadUserFile({
        body: formData
      }, postUserDocuments, { body: { document_type: documentType } })
    } else {
      message.error(this.intlText({ id: 'Salah format, harap unggah hanya gif/jpeg/png/pdf' }))
    }
  }

  render () {
    const {
      // userDocuments,
      index,
      type,
      documents,
      display_name: displayName
    } = this.props
    return (
      <DocumentsGroupStyle>
        <div className='documents-container'>
          <div className='document-section-name'>
            {index + 1}. <IntlMessages id={this.intlText({ id: displayName })} />
          </div>
          <Row type='flex'>
            {documents.map((document, index) => (
              <Col xs={10} sm={4} md={4} lg={4} xl={4} className='document-items-img'>
                <DocumentItem {...document} type={type} />
              </Col>
            ))}
            <Col xs={10} sm={4} md={4} lg={4} xl={4}>
              <Upload
                listType='picture-card'
                showUploadList={false}
                multiple={false}
                customRequest={this.customRequest}
              >
                <Icon type='upload' className='documents-upload-icon' />
              </Upload>
            </Col>
          </Row>
        </div>
      </DocumentsGroupStyle>
    )
  }
}

DocumentsGroup.propTypes = {
  documents: PropTypes.array,
  display_name: PropTypes.string,
  type: PropTypes.string
}

DocumentsGroup.defaultProps = {
  documents: [],
  display_name: '',
  type: ''
}

export default connect(
  state => ({
  }),
  {
    uploadUserFile
  }
)(injectIntl(DocumentsGroup))
