import React, { Component } from 'react'
import { connect } from 'react-redux'
import {
  Spin,
  Icon,
  notification,
  Modal
} from 'antd'
import { injectIntl } from 'react-intl'
import PropTypes from 'prop-types'
import { Document, Page } from 'react-pdf'
import DocumentItemStyle from './index.style'
import userActions from '../../../../redux/user/actions'
import getUrlExtension from '../../../../helpers/getExtensionUrl'
import IntlMessages from '../../../../components/utility/intlMessages'

const {
  uploadUserFile,
  putUserDocuments,
  deleteUserDocuments
} = userActions

class DocumentItem extends Component {
  state = {
    previewImage: '',
    previewVisible: false
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  customRequest = ({ file }) => {
    /*
      custom request to upload file
    */
    const { type: fileType } = file
    const { id, type: documentType } = this.props
    const validImageTypes = ['image/gif', 'image/jpeg', 'image/png', 'application/pdf']
    if (validImageTypes.includes(fileType)) {
      const formData = new FormData()
      formData.append('file', file)
      this.props.uploadUserFile({
        body: formData
      }, putUserDocuments, { body: { id, document_type: documentType } })
    } else {
      notification.error({
        message: this.intlText({ id: 'Salah format, harap unggah hanya gif/jpeg/png/pdf/doc' })
      })
    }
  }

  renderThumbnail (url, name) {
    const extentsion = getUrlExtension(url)
    switch (extentsion) {
      case 'pdf':
        return (
          <Document
            file={{ url }}
            error={this.intlText({ id: 'Failed to load PDF' })}
          >
            <a href={url} target='_blank'>
              <Page
                pageNumber={1}
                className='document-card-item-pdf'
                renderTextLayer={false}
              />
            </a>
          </Document>
        )

      case 'doc':
        return ((<a
          className='video-file'
          href={url}
          target='_blank'
          rel='noopener noreferrer'
        >
          <IntlMessages
            id='View File'
          />
        </a>)
        )
      default:
        return (
          <img
            src={url}
            alt={name}
            className='document-card-item'
            onClick={() => this.handlePreview(url)}
          />
        )
    }
  }

  handlePreview = file => {
    this.setState({
      previewImage: file,
      previewVisible: true
    })
  }

  handleClosePreview = () => {
    this.setState({
      previewVisible: false
    })
  }

  render () {
    const {
      id,
      url,
      name,
      putUserDocumentsLoading,
      deleteUserDocumentsLoading,
      updatingDocumentId
    } = this.props
    const {
      previewImage,
      previewVisible
    } = this.state
    const beingUpdated = updatingDocumentId === id
    return (
      <DocumentItemStyle>
        <Modal visible={previewVisible} footer={null} onCancel={this.handleClosePreview}>
          <img alt='images' style={{ width: '100%' }} src={previewImage} />
        </Modal>
        <Spin spinning={beingUpdated && (!!putUserDocumentsLoading || !!deleteUserDocumentsLoading)}>
          <div className='document-item-card'>
            {this.renderThumbnail(url, name)}
            <div className='document-item-delete-box'>
              <div
                className='document-item-delete-circle'
                onClick={
                  () => this.props.deleteUserDocuments({ body: { id } })
                }>
                <Icon type='delete' theme='filled' className='doc-item-icon' />
              </div>
            </div>
          </div>
        </Spin>
      </DocumentItemStyle>
    )
  }
}

DocumentItem.propTypes = {
  userDocuments: PropTypes.array
}

DocumentItem.defaultProps = {
  userDocuments: []
}

export default connect(
  state => ({
    putUserDocumentsLoading: state.Loading.PUT_USER_DOCUMENTS,
    deleteUserDocumentsLoading: state.Loading.DELETE_USER_DOCUMENTS,
    updatingDocumentId: state.User.updatingDocumentId
  }),
  {
    uploadUserFile,
    deleteUserDocuments
  }
)(injectIntl(DocumentItem))
