const getUrlExtension = url => {
  if (Array.isArray(url)) {
    const arrUrl = url.map(val => {
      return val
      .split(/\#|\?/)[0] // eslint-disable-line
        .split('.')
        .pop()
        .trim()
    })
    return arrUrl
  } else {
    if (url !== null) {
      return url
        .split(/\#|\?/)[0] // eslint-disable-line
        .split('.')
        .pop()
        .trim()
    }
  }
}

export default getUrlExtension
