import React, { Component } from 'react'
import { connect } from 'react-redux'
import DocumentsWrapper from './documents.style'
import {
  Row,
  Col,
  Alert,
  notification
} from 'antd'
import { injectIntl } from 'react-intl'
import PropTypes from 'prop-types'
import userActions from '../../redux/user/actions'
import DocumentsGroup from './components/DocumentsGroup'
import CircularLoader from '../../components/CircularLoader'

const {
  getUserDocuments,
  resetUserRedux
} = userActions

class Documents extends Component {
  componentDidMount () {
    this.props.getUserDocuments()
  }

  componentWillReceiveProps (nextProps) {
    const {
      getUserDocumentsLoading,
      getUserDocumentsError,
      getUserDocumentsMessage,
      uploadUserFileLoading,
      uploadUserFileError,
      uploadUserFileMessage,
      putUserDocumentsLoading,
      putUserDocumentsError,
      putUserDocumentsMessage,
      deleteUserDocumentsLoading,
      deleteUserDocumentsError,
      deleteUserDocumentsMessage
    } = nextProps

    if (!getUserDocumentsLoading && !!getUserDocumentsError && getUserDocumentsMessage) {
      notification.error({
        message: this.intlText({ id: getUserDocumentsMessage })
      })
      this.props.resetUserRedux(['getUserDocumentsMessage'])
    }

    if (!uploadUserFileLoading && uploadUserFileMessage) {
      notification[uploadUserFileError ? 'error' : 'success']({
        message: this.intlText({ id: uploadUserFileMessage })
      })
      this.props.resetUserRedux(['uploadUserFileMessage'])
    }

    if (!putUserDocumentsLoading && putUserDocumentsMessage) {
      notification[putUserDocumentsError ? 'error' : 'success']({
        message: this.intlText({ id: putUserDocumentsMessage })
      })
      this.props.resetUserRedux(['putUserDocumentsMessage'])
    }

    if (!deleteUserDocumentsLoading && deleteUserDocumentsMessage) {
      notification[deleteUserDocumentsError ? 'error' : 'success']({
        message: this.intlText({ id: deleteUserDocumentsMessage })
      })
      this.props.resetUserRedux(['deleteUserDocumentsMessage'])
    }
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  render () {
    const {
      userDocuments,
      getUserDocumentsLoading,
      getUserDocumentsError,
      getUserDocumentsMessage,
      uploadUserFileLoading,
      uploadUserFileError,
      uploadUserFileMessage
    } = this.props
    return (
      <DocumentsWrapper>
        <Row type='flex' style={{ width: '100%' }}>
          <Col xs={24} sm={24} className={`${(!!getUserDocumentsLoading || !!uploadUserFileLoading) && 'doc-loader-margin'}`}>
            <CircularLoader isSpining={!!getUserDocumentsLoading || !!uploadUserFileLoading} size='24px'>
              {!getUserDocumentsLoading && !!getUserDocumentsError && getUserDocumentsMessage && (
                <Alert type='error' description={getUserDocumentsMessage} />
              )}
              {!uploadUserFileLoading && !!uploadUserFileError && uploadUserFileMessage && (
                <Alert type='error' description={uploadUserFileMessage} />
              )}
              {userDocuments.map((userDocument, index) => (
                <DocumentsGroup {...userDocument} index={index} key={index} />
              ))}
            </CircularLoader>
          </Col>
        </Row>
      </DocumentsWrapper>
    )
  }
}

Documents.propTypes = {
  userDocuments: PropTypes.array
}

Documents.defaultProps = {
  userDocuments: []
}

export default connect(
  state => ({
    userDocuments: state.User.userDocuments,
    getUserDocumentsLoading: state.Loading.GET_USER_DOCUMENTS,
    getUserDocumentsError: state.Error.GET_USER_DOCUMENTS,
    getUserDocumentsMessage: state.User.getUserDocumentsMessage,
    uploadUserFileLoading: state.Loading.UPLOAD_USER_FILE,
    uploadUserFileError: state.Error.UPLOAD_USER_FILE,
    uploadUserFileMessage: state.User.uploadUserFileMessage,
    putUserDocumentsLoading: state.Loading.PUT_USER_DOCUMENTS,
    putUserDocumentsError: state.Error.PUT_USER_DOCUMENTS,
    deleteUserDocumentsLoading: state.Loading.DELETE_USER_DOCUMENTS,
    deleteUserDocumentsError: state.Error.DELETE_USER_DOCUMENTS,
    putUserDocumentsMessage: state.User.putUserDocumentsMessage,
    deleteUserDocumentsMessage: state.User.deleteUserDocumentsMessage
  }),
  {
    getUserDocuments,
    resetUserRedux
  }
)(injectIntl(Documents))
